[{"order":1,"type":"heading","text":"Advanced TypeScript Features in Angular: Mapped Types, Conditional Types, and Utility Types"},{"order":2,"type":"paragraph","text":"TypeScript's advanced features provide powerful tools for creating type-safe and maintainable Angular applications. This tutorial explores Mapped Types, Conditional Types, and Utility Types, demonstrating how they can enhance your code."},{"order":3,"type":"heading","text":"Mapped Types"},{"order":4,"type":"paragraph","text":"Mapped types allow you to transform existing types by iterating over their properties. This is useful for creating new types based on existing ones, such as making all properties optional or read-only."},{"order":5,"type":"subheading","text":"Basic Mapped Type Example"},{"order":6,"type":"code","text":"interface Person {
  name: string;
  age: number;
}

type PartialPerson = {
  [K in keyof Person]?: Person[K];
};

// PartialPerson is equivalent to:
// {
//   name?: string;
//   age?: number;
// }
"},{"order":7,"type":"paragraph","text":"In this example, 'PartialPerson' is a mapped type that makes all properties of the 'Person' interface optional. 'keyof Person' gets all the keys of the 'Person' interface ('name' and 'age'). 'K in keyof Person' iterates over these keys. 'Person[K]' gets the type of each property."},{"order":8,"type":"subheading","text":"Readonly Mapped Type"},{"order":9,"type":"code","text":"interface Person {
  name: string;
  age: number;
}

type ReadonlyPerson = {
  readonly [K in keyof Person]: Person[K];
};

// ReadonlyPerson is equivalent to:
// {
//   readonly name: string;
//   readonly age: number;
// }
"},{"order":10,"type":"paragraph","text":"This example creates a 'ReadonlyPerson' type where all properties are read-only."},{"order":11,"type":"heading","text":"Conditional Types"},{"order":12,"type":"paragraph","text":"Conditional types allow you to define types based on conditions, similar to a ternary operator in JavaScript. They use the 'infer' keyword to extract type information."},{"order":13,"type":"subheading","text":"Basic Conditional Type Example"},{"order":14,"type":"code","text":"type NonNullable<T> = T extends null | undefined ? never : T;

type StringOrNull = string | null | undefined;
type JustString = NonNullable<StringOrNull>; // string
"},{"order":15,"type":"paragraph","text":"The 'NonNullable' type checks if 'T' extends 'null' or 'undefined'. If it does, it returns 'never' (meaning the type is not possible). Otherwise, it returns 'T'. This effectively removes 'null' and 'undefined' from the type."},{"order":16,"type":"subheading","text":"Infer Keyword Example"},{"order":17,"type":"code","text":"type ReturnType<T extends (...args: any) => any> = T extends (...args: any) => infer R ? R : any;

function add(a: number, b: number): number {
  return a + b;
}

type AddReturnType = ReturnType<typeof add>; // number
"},{"order":18,"type":"paragraph","text":"The 'ReturnType' type extracts the return type of a function. 'T extends (...args: any) => any' ensures that 'T' is a function. 'T extends (...args: any) => infer R ? R : any' uses 'infer R' to infer the return type of the function and assigns it to 'R'. If it can't infer the return type, it defaults to 'any'."},{"order":19,"type":"heading","text":"Utility Types"},{"order":20,"type":"paragraph","text":"TypeScript provides several built-in utility types that perform common type transformations. These can save you time and effort when working with complex types."},{"order":21,"type":"subheading","text":"Partial<T>"},{"order":22,"type":"paragraph","text":"Makes all properties in 'T' optional."},{"order":23,"type":"code","text":"interface Person {
  name: string;
  age: number;
}

type PartialPerson = Partial<Person>;

// Equivalent to:
// {
//   name?: string;
//   age?: number;
// }
"},{"order":24,"type":"subheading","text":"Readonly<T>"},{"order":25,"type":"paragraph","text":"Makes all properties in 'T' read-only."},{"order":26,"type":"code","text":"interface Person {
  name: string;
  age: number;
}

type ReadonlyPerson = Readonly<Person>;

// Equivalent to:
// {
//   readonly name: string;
//   readonly age: number;
// }
"},{"order":27,"type":"subheading","text":"Required<T>"},{"order":28,"type":"paragraph","text":"Makes all properties in 'T' required."},{"order":29,"type":"code","text":"interface Person {
  name?: string;
  age?: number;
}

type RequiredPerson = Required<Person>;

// Equivalent to:
// {
//   name: string;
//   age: number;
// }
"},{"order":30,"type":"subheading","text":"Pick<T, K>"},{"order":31,"type":"paragraph","text":"Selects a set of properties 'K' from 'T'."},{"order":32,"type":"code","text":"interface Person {
  name: string;
  age: number;
  address: string;
}

type NameAndAge = Pick<Person, 'name' | 'age'>;

// Equivalent to:
// {
//   name: string;
//   age: number;
// }
"},{"order":33,"type":"subheading","text":"Omit<T, K>"},{"order":34,"type":"paragraph","text":"Removes a set of properties 'K' from 'T'."},{"order":35,"type":"code","text":"interface Person {
  name: string;
  age: number;
  address: string;
}

type PersonWithoutAddress = Omit<Person, 'address'>;

// Equivalent to:
// {
//   name: string;
//   age: number;
// }
"},{"order":36,"type":"subheading","text":"Record<K, T>"},{"order":37,"type":"paragraph","text":"Constructs a type with a set of properties 'K' of type 'T'."},{"order":38,"type":"code","text":"type Fruit = 'apple' | 'banana' | 'orange';

type FruitPrices = Record<Fruit, number>;

// Equivalent to:
// {
//   apple: number;
//   banana: number;
//   orange: number;
// }
"},{"order":39,"type":"subheading","text":"Exclude<T, U>"},{"order":40,"type":"paragraph","text":"Excludes from 'T' all types that are assignable to 'U'."},{"order":41,"type":"code","text":"type AvailableColors = 'red' | 'green' | 'blue';
type UnavailableColors = 'red' | 'yellow';

type ActualAvailableColors = Exclude<AvailableColors, UnavailableColors>; // 'green' | 'blue'
"},{"order":42,"type":"subheading","text":"Extract<T, U>"},{"order":43,"type":"paragraph","text":"Extracts from 'T' all types that are assignable to 'U'."},{"order":44,"type":"code","text":"type AvailableColors = 'red' | 'green' | 'blue';
type UnavailableColors = 'red' | 'yellow';

type SharedColors = Extract<AvailableColors, UnavailableColors>; // 'red'
"},{"order":45,"type":"subheading","text":"NonNullable<T>"},{"order":46,"type":"paragraph","text":"Excludes 'null' and 'undefined' from 'T'."},{"order":47,"type":"code","text":"type StringOrNull = string | null | undefined;
type JustString = NonNullable<StringOrNull>; // string
"},{"order":48,"type":"subheading","text":"Parameters<T>"},{"order":49,"type":"paragraph","text":"Obtains the parameters of a function type in a tuple."},{"order":50,"type":"code","text":"type MyFunc = (a: number, b: string) => void;
type MyFuncParams = Parameters<MyFunc>; // [number, string]
"},{"order":51,"type":"subheading","text":"ConstructorParameters<T>"},{"order":52,"type":"paragraph","text":"Obtains the parameters of a constructor function type in a tuple."},{"order":53,"type":"code","text":"class MyClass {
  constructor(a: number, b: string) {}
}
type MyClassParams = ConstructorParameters<typeof MyClass>; // [number, string]
"},{"order":54,"type":"subheading","text":"ReturnType<T>"},{"order":55,"type":"paragraph","text":"Obtains the return type of a function type."},{"order":56,"type":"code","text":"type MyFunc = (a: number, b: string) => boolean;
type MyFuncReturnType = ReturnType<MyFunc>; // boolean
"},{"order":57,"type":"subheading","text":"InstanceType<T>"},{"order":58,"type":"paragraph","text":"Obtains the instance type of a constructor function type."},{"order":59,"type":"code","text":"class MyClass {
  constructor(a: number, b: string) {}
}
type MyClassInstance = InstanceType<typeof MyClass>; // MyClass
"},{"order":60,"type":"subheading","text":"Template Literal Types"},{"order":61,"type":"paragraph","text":"Template literal types build on string literal types, and have the ability to expand into a large number of string literals via unions. They have the same syntax as template literal strings in JavaScript, but are used in type positions."},{"order":62,"type":"code","text":"type Color = "red" | "blue";
type Quantity = "one" | "two";

type ColoredQuantity = `${Quantity} ${Color}`;

// type ColoredQuantity = "one red" | "one blue" | "two red" | "two blue"
"},{"order":63,"type":"heading","text":"Conclusion"},{"order":64,"type":"paragraph","text":"Mapped Types, Conditional Types, and Utility Types are powerful tools in TypeScript that can significantly improve the type safety and maintainability of your Angular applications. By understanding and utilizing these features, you can write more robust and expressive code."}]
